@@ -0,0 +1,15 @@
+name: synth
+description: "Synth starter kit: filtered saw lead, square bass, arpeggio, punchy drums (edit freely)."
+instruments:
+  l: { name: saw_lead, osc: saw, unison: 2, detune: 6, env: [0.004, 0.2, 0.7, 0.12], filter: { type: lp, cutoff: 1800, resonance: 0.35, env_amount: 2.0, env: [0.002, 0.25, 0.2, 0.1] }, gain: -9, range: [C3, C6] }
+  m: { name: square_bass, osc: pulse, duty: 0.5, env: [0.002, 0.12, 0.8, 0.05], filter: { type: lp, cutoff: 900, resonance: 0.2, env_amount: 1.5, env: [0.001, 0.12, 0.0, 0.05] }, gain: -4, range: [E1, C4] }
+  a: { name: arp, osc: pulse, duty: 0.25, arp: [0, 7, 12, 7], arp_rate: 24, env: [0.002, 0.1, 0.6, 0.08], gain: -12, range: [C3, C6] }
+  z: { name: zap, osc: pulse, duty: 0.3, pitch_env: [12, 0.08], env: [0.001, 0.12, 0.0, 0.03], gain: -11, range: [C3, C6] }
+  k: { name: kick, drum: kick, tune: 48, decay: 0.3, punch: 34, click: 0.4, gain: -1 }
+  s: { name: snare, drum: snare, tune: 180, noise: 0.6, decay: 0.18, tone: 3800, gain: -5 }
+  c: { name: clap, drum: clap, decay: 0.2, tone: 1400, gain: -8 }
+  h: { name: hat, drum: hat, decay: 0.04, tone: 9000, gain: -14 }
+groups:
+  leads: [l, a]
+  bass: [m]
+  drums: [k, s, c, h]
